def parse_metadata_block(body: str) -> dict:
    """Read the identity block back. Returns {} when absent.

    Uses the same innermost-well-formed-pair search as :func:`_metadata_bounds`
    so the reader and the writer agree on which block is authoritative. A body
    that quotes an unfinished example -- before or after the real block -- must
    not have that example's fields bleed into the parsed result, whether by
    widening the span read or by supplying a field the real block never set.
    """
    if not body or METADATA_BEGIN not in body:
        return {}
    bounds = _metadata_bounds(body)
    if bounds is None:
        return {}
    start, end = bounds
    inner = body[start + len(METADATA_BEGIN) : end - len(METADATA_END)]
    fields: dict = {}
